package cn.zhuatech.dqm.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class DataProductReleaseServiceTest{private final DataProductReleaseService service=new DataProductReleaseService();@Test void publishesTrustedProduct(){var r=service.assess(new DataProductReleaseService.Request("DP1",true,true,true,true,0,true,96,10,30));assertThat(r.decision()).isEqualTo(DataProductReleaseService.Decision.PUBLISH);}@Test void blocksGovernanceFailures(){var r=service.assess(new DataProductReleaseService.Request("DP2",false,false,false,false,2,false,96,10,30));assertThat(r.blockers()).hasSize(6);}@Test void reviewsQualityAndFreshness(){var r=service.assess(new DataProductReleaseService.Request("DP3",true,true,true,true,0,true,80,60,30));assertThat(r.actions()).hasSize(2);}}
